import { MeshBasicNodeMaterial } from 'three/webgpu';
import { Group, Mesh, PlaneGeometry } from 'three';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // --------- Plane Mesh ----------
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    map: null,
  });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left',
    });
    group.add(txt);
  }

  // --------- User Data ----------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    // Dispose material and geometry
    if (material.map) material.map.dispose();
    material.dispose();
    geometry.dispose();

    // Dispose any text resources
    group.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose?.();
      }
    });

    // Kill GSAP timelines (none in this node but safe)
    gsap.globalTimeline.clear();
  };

  return group;
}
